type Item =
  | { kind: 'pedido'; total: number }               // comida entregue: bem físico
  | { kind: 'assinatura-pro'; plano: 'mensal' }     // recurso digital usado no app
  | { kind: 'credito-gorjeta'; valor: number };     // gorjeta para o entregador: serviço fora do app

type Meio = 'loja' | 'gateway';

// Regra geral das lojas: digital consumido no app → compra da loja (IAP);
// bem físico ou serviço consumido fora do app → outro meio (gateway, Pix)
export function meioDePagamento(item: Item): Meio {
  switch (item.kind) {
    case 'assinatura-pro':
      return 'loja';
    case 'pedido':
    case 'credito-gorjeta':
      return 'gateway';
  }
}

