import { useEffect, useState } from 'react';
import { Alert, Button, Platform, View } from 'react-native';
import Purchases, { type PurchasesPackage } from 'react-native-purchases';

// Na abertura do app, uma vez (chave pública da plataforma; o id liga as compras à conta)
Purchases.configure({
  apiKey: Platform.OS === 'ios' ? process.env.EXPO_PUBLIC_RC_IOS_KEY! : process.env.EXPO_PUBLIC_RC_ANDROID_KEY!,
  appUserID: usuario.id,
});

export function Paywall({ onUnlocked }: { onUnlocked: () => void }) {
  const [pacotes, setPacotes] = useState<PurchasesPackage[]>([]);

  useEffect(() => {
    // Preços vêm da loja, já no formato e na moeda da pessoa
    Purchases.getOfferings().then((o) => setPacotes(o.current?.availablePackages ?? []));
  }, []);

  async function comprar(pacote: PurchasesPackage) {
    try {
      const { customerInfo } = await Purchases.purchasePackage(pacote);
      if (customerInfo.entitlements.active['pro']) onUnlocked();
    } catch (e: any) {
      if (!e.userCancelled) Alert.alert('Não foi possível concluir a compra');
    }
  }

  return (
    <View>
      {pacotes.map((p) => (
        <Button key={p.identifier} title={`${p.product.title} · ${p.product.priceString}`} onPress={() => comprar(p)} />
      ))}
    </View>
  );
}

import Purchases from 'react-native-purchases';

// Acesso vem do direito ativo, não de um produto específico
export async function isPro(): Promise<boolean> {
  const info = await Purchases.getCustomerInfo(); // usa cache e atualiza em segundo plano
  return info.entitlements.active['pro'] !== undefined;
}

// Botão "Restaurar compras": aparelho novo, app reinstalado ou outra conta da loja
export async function restaurar(): Promise<boolean> {
  const info = await Purchases.restorePurchases();
  return info.entitlements.active['pro'] !== undefined;
}

