import { useStripe } from '@stripe/stripe-react-native';
import { Alert } from 'react-native';

export function useCheckout() {
  const { initPaymentSheet, presentPaymentSheet } = useStripe();

  return async function pagar(pedidoId: string) {
    // 1. O backend calcula o valor e cria o PaymentIntent; o app nunca define o preço
    const { clientSecret } = await api.post(`/pedidos/${pedidoId}/pagamento`).then((r) => r.data);

    // 2. A folha de pagamento do Stripe coleta o cartão (tokenizado, sem passar pelo app)
    const init = await initPaymentSheet({ merchantDisplayName: 'Cardápio', paymentIntentClientSecret: clientSecret });
    if (init.error) return Alert.alert('Erro', init.error.message);

    const { error } = await presentPaymentSheet();
    if (error) return error.code === 'Canceled' ? undefined : Alert.alert('Pagamento recusado', error.message);

    // 3. Sucesso na tela não confirma o pedido: o backend confirma pelo webhook
    navegarPara(`/pedidos/${pedidoId}/acompanhar`);
  };
}

import express from 'express';
import Stripe from 'stripe';

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!);
const app = express();

// Corpo cru: a assinatura é calculada sobre os bytes exatos que o Stripe enviou
app.post('/webhooks/stripe', express.raw({ type: 'application/json' }), async (req, res) => {
  let event: Stripe.Event;
  try {
    event = stripe.webhooks.constructEvent(req.body, req.header('stripe-signature')!, process.env.STRIPE_WEBHOOK_SECRET!);
  } catch {
    return res.sendStatus(400); // assinatura inválida: não veio do Stripe
  }

  // Idempotência: o mesmo evento pode chegar mais de uma vez
  const novo = await db.eventos.inserirSeNaoExiste(event.id); // UNIQUE em event.id
  if (!novo) return res.sendStatus(200);

  if (event.type === 'payment_intent.succeeded') {
    const intent = event.data.object;
    await db.pedidos.marcarComoPago(intent.metadata.pedidoId, intent.id);
  }
  res.sendStatus(200); // responder rápido; trabalho pesado vai para uma fila
});
